<?php $id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT i.*,e.name,e.description,c.name category FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id JOIN equipment_categories c ON c.id=e.category_id WHERE i.id=?');$q->execute([$id]);$r=$q->fetch();if(!$r)redirect('?page=equipment');$q=$pdo->prepare('SELECT l.*,b.full_name borrower FROM loans l JOIN borrowers b ON b.id=l.borrower_id WHERE l.item_id=? ORDER BY l.issued_at DESC');$q->execute([$id]);$history=$q->fetchAll();layout_start('Equipment details','equipment'); ?><div class="page-heading"><div><a class="back-link" href="?page=equipment">← Equipment inventory</a><h1><?=h($r['name'])?></h1><p class="muted"><?=h($r['asset_code'])?> · <?=h($r['category'])?></p></div><a class="button secondary" href="?page=equipment-form&id=<?=$id?>">Edit record</a></div><div class="detail-grid"><section class="panel"><h2>Item details</h2><dl class="detail-list"><dt>Status</dt><dd><span class="badge <?=strtolower(str_replace(' ','-',$r['status']))?>"><?=h($r['status'])?></span></dd><dt>Condition</dt><dd><?=h($r['condition_label'])?></dd><dt>Description</dt><dd><?=h($r['description']?:'No description added.')?></dd><dt>Notes</dt><dd><?=h($r['notes']?:'No notes.')?></dd><dt>Added</dt><dd><?=date('j M Y',strtotime($r['created_at']))?></dd></dl></section><section class="panel"><h2>Loan history</h2><?php if(!$history): ?><p class="muted">This item has no loan history yet.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>Borrower</th><th>Issued</th><th>Returned</th></tr></thead><tbody><?php foreach($history as $l): ?><tr><td><?=h($l['borrower'])?></td><td><?=date('j M Y',strtotime($l['issued_at']))?></td><td><?=$l['returned_at']?date('j M Y',strtotime($l['returned_at'])):'Active'?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div><?php layout_end();
